// TH14 v1.00b Stage 2 midboss, nonspell MBoss1.
// Source: st02mbs.ecl.txt:49-78 (entry). Dependencies:
//   MBoss1At:80-98, MBoss1_at:100-121, MBoss1_at2:123-137,
//   MPhantom01:384-406, MPhantom1_at:408-435.
// Card frames: 0..119 = common 120-frame Bezier entry already consumed at
// MBoss:32-33; the boss is spawned at its post-entry position (0,128) with the
// common boxes/limit. Source MBoss1 starts at source timer 120, so card frame
// == source timer frame. Native slot0/slot1 timeout is 1680 (1680-120 = 1560
// frames of MBoss1 content), then the source escape cleanup. Card window adds
// 360 frames of tail allowance.

const TIME_LIMIT: int = 2164;        // 120 buffer + 2040 window + 4 start margin
const OPENING_BUFFER: int = 120;     // source entry frames already used by MBoss:15-33
const WAVE_DEADLINE: int = 1560;     // 1680 source timeout minus 120 entry frames
const WALK_FRAMES: int = 120;        // source moveRand(120, 4, 0.75)

// TH14 synthetic appearance aliases (transcribe/th14/touhou-bullets.ecl):
// source type 8 -> TH14_RICE, source type 10 -> TH14_SHARD.
const TH14_RICE: int = 480;
const TH14_SHARD: int = 512;
const RICE_COLOR: int = 2;           // source etSprite(0, 8, 2)
const SHARD_COLOR: int = 6;          // source etSprite(0, 10, 6)

// Source MBoss1_at EX: ANIM(type2,a=1) -> WAIT 200 -> DELETE(a=0). Birth
// animation is omitted by policy; the WAIT+DELETE becomes a 200-frame lifetime.
xformdef RICE_LIFE {
    wait(200);
    set_life(1);
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// Training shell: control owns the phase but never collides and is exempt from
// the boss's enmKillAll cleanup so the phase keeps its own timer.
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Common MBoss init: lifeSet(12000), hurtbox 48/2, hitbox 40/2, limit
    // moveLimit(0,128,280,48); entry position after the Bezier is (0,128).
    _ = spawn_enemy(0fx, 128fx, 12000, 0, 0, 0, boss);
}

async sub boss() {
    set_invuln(65535);
    set_hurtbox(24fx);
    set_hitbox(20fx);
    spawn phantom_spawner();
    var t: int = 0;
    loop {
        wait(60);              // MBoss1_204: EffChargePoint3 (presentation) + wait(60)
        t = t + 60;
        wait(30);              // anmSelect/anmSelectedPlay (presentation) + wait(30)
        t = t + 30;
        spawn_wave();          // diffF% A / diffI$ B ring of MBoss1At children
        wait(60);
        t = t + 60;
        var n: int = WALK_FRAMES;
        if t + n > WAVE_DEADLINE { n = WAVE_DEADLINE - t; }
        if n < 1 { break; }
        move_rand_walk(n);     // moveRand(120, 4, 0.75) then its wait(120)
        t = t + n;
        if t >= WAVE_DEADLINE { break; }
    }
    // Timeout exit (MBossEscape): enmKillAll + etClear(640) + movePosTime exit.
    kill_all_enemies(KILL_SILENT);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_to(60, -224fx, 64fx, EASE_QUAD_OUT);
    wait(60);
}

// MBoss1: %F0=0.392699 rad (22.5 deg); diffF: 45/45/30/22.5 deg step;
// diffI: 8/8/12/16 children. Children inherit the parent F0 angle, here passed
// by value at creation.
sub spawn_wave() {
    var rank: int = global(GVAR_RANK);
    var step: int = 8192;      // 45 deg
    var count: int = 8;
    if rank == RANK_HARD {
        step = 5461;           // 30 deg
        count = 12;
    } else if rank == RANK_LUNATIC {
        step = 4096;           // 22.5 deg
        count = 16;
    }
    for i in 0..count {
        var dir: int = 4096 + i * step;   // 22.5 deg + i*step, unwrapped BAM
        _ = spawn_enemy($self_x, $self_y, 10, 0, 10, 0, wave_child(dir as angle));
    }
}

// MBoss1At: flags 288 = 0x120 has 0x20 (no body collision / no damage gate);
// 32 px first tick then 1 px/frame; every 60 frames a 120-frame mode-7 turn of
// RANDRAD/450 per frame (replaced at 60, i.e. a 60-frame linear turn here).
async sub wave_child(dir: angle) {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_vel(0, dir, 32fx, EASE_LINEAR);
    wait(1);
    move_vel(0, dir, 1fx, EASE_LINEAR);
    spawn wave_fire();
    for i in 0..10 {
        wait(60);
        var turn: int = (rand(65536) - 32768) / 450;
        move_angle(60, $self_angle + ((turn * 60) as angle), EASE_LINEAR);
    }
}

// MBoss1_at: one rice (type 8 color 2) every 4 frames along ABS_ANGLE, speed
// 0.01, 200-frame life. ANIM birth displacement -4*speed = -0.04 px.
async sub wave_fire() {
    sh_reset(0);
    sh_sprite(0, TH14_RICE, RICE_COLOR);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 1, 1);
    sh_speed(0, 0.01fx, 0fx);
    sh_dist(0, -0.04fx);
    sh_xform(0, RICE_LIFE);
    loop {
        sh_angle(0, $self_angle, 0deg);
        sh_fire(0);
        wait(4);
    }
}

// MBoss1_at2: wait(200), then math93(%A,%B,96,144) every 100 frames; %B*0.3.
// math93 is documented only as "random point" with unverified r1/r2 geometry;
// this card uses the natural ellipse reading (96*cos, 144*sin) and reports it.
// The source keeps spawning past the 1680 timeout and the next attack's
// killAllAsync cleans it; this card has no next attack, so stop at the same
// deadline the segment cleanup uses.
async sub phantom_spawner() {
    wait(200);
    var t: int = 200;
    loop {
        if t >= WAVE_DEADLINE { break; }
        var phase: int = rand(65536) - 32768;
        var ox: fx = 96fx * cos(phase as angle);
        var oy: fx = 144fx * sin(phase as angle);
        oy = oy * 0.3fx;
        _ = spawn_enemy($self_x + ox, $self_y + oy, 200, 0, 10, 0, phantom);
        wait(100);
        t = t + 100;
    }
}

// MPhantom01: hurtbox 28/2, hitbox 16/2, aimed 5-frame volleys (!NHL only),
// moveVel(ANGLE_PLAYER,0) + moveSpeedTime(120, mode3, 0.2) and
// moveEllipseRel(RANDRAD, 1deg/frame, r=64, d=0, axis=0, ratio=0).
// ratio=0,axis=0 reduces the REL layer to (0, 64*sin(theta)); C=(0,0).
async sub phantom() {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    if global(GVAR_RANK) >= RANK_NORMAL {
        spawn phantom_fire();
    }
    var dir: angle = aim_player();
    var theta: int = rand(65536) - 32768;   // RANDRAD
    var sx: fx = $self_x;
    var sy: fx = $self_y;
    var cx: fx = cos(dir);
    var cy: fx = sin(dir);
    var cum: fx = 0fx;
    var lx: fx = sx;
    var ly: fx = sy + 64fx * sin(theta as angle);
    move_vel_xy(0, lx - sx, ly - sy, EASE_LINEAR);   // setter's immediate REL jump
    var t: int = 0;
    loop {
        wait(1);
        t = t + 1;
        var sp: fx = 0.2fx;
        if t < 120 {
            var u: fx = (t as fx) / (120 as fx);
            var u2: fx = u * u;
            sp = 0.2fx * u2 * u2;          // mode 3 = EASE_QUART_IN
        }
        cum = cum + sp;
        theta = theta + 182;               // 0.017453292 rad/frame
        var nx: fx = sx + cx * cum;
        var ny: fx = sy + cy * cum + 64fx * sin(theta as angle);
        move_vel_xy(0, nx - lx, ny - ly, EASE_LINEAR);
        lx = nx;
        ly = ny;
    }
}

// MPhantom1_at: mode1 fan, 1 way, type 10 color 6; etCountD layers
// 1/1/4/8 and etSpeedD s0 1.0/1.8/3.0/4.0 with s1=1.0.
async sub phantom_fire() {
    var rank: int = global(GVAR_RANK);
    var m: int = 1;
    var s0: fx = 1.8fx;
    var step: fx = 0fx;
    if rank == RANK_HARD {
        m = 4;
        s0 = 3fx;
        step = (1fx - 3fx) / (3 as fx);
    } else if rank == RANK_LUNATIC {
        m = 8;
        s0 = 4fx;
        step = (1fx - 4fx) / (7 as fx);
    }
    sh_reset(0);
    sh_sprite(0, TH14_SHARD, SHARD_COLOR);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, 1, m);
    sh_speed(0, s0, step);
    wait(120);
    for c in 0..60 {
        sh_angle(0, aim_player(), 0deg);
        for v in 0..4 {
            sh_fire(0);
            wait(5);
        }
        wait(60);
    }
}

// moveRand(120, 4, 0.75) with moveLimit(0,128,280,48): position clamp
// x in [-140,140], y in [104,152]; direction selection inner region x +-70,
// y 116..140. Speed per tick k is 0.75*(1-k/120) (linear, mode-0 inherited).
sub move_rand_walk(n: int) {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var pick: int = rand(65536) % 3;
        if $player_x > $self_x {
            if pick == 0 { a = a + 32768; }
        } else {
            if pick != 0 { a = a + 32768; }
        }
    }
    if $self_y < 116fx {
        if a < 0 { a = -a; }
    } else if $self_y > 140fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    var dir: angle = a as angle;
    var cx: fx = cos(dir);
    var cy: fx = sin(dir);
    for kk in 0..n {
        var k: int = kk + 1;
        var sp: fx = ((WALK_FRAMES - k) as fx) / (WALK_FRAMES as fx) * 0.75fx;
        var nx: fx = $self_x + cx * sp;
        var ny: fx = $self_y + cy * sp;
        if nx < -140fx { nx = -140fx; }
        if nx > 140fx { nx = 140fx; }
        if ny < 104fx { ny = 104fx; }
        if ny > 152fx { ny = 152fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        wait(1);
    }
}
